use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/crt-euler-direct176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-05-crt-euler-direct176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn copy(a:impl AsRef<Path>,b:impl AsRef<Path>){let(a,b)=(a.as_ref(),b.as_ref());fs::create_dir_all(b.parent().unwrap()).unwrap();fs::copy(a,b).unwrap();assert_eq!(hash(a),hash(b));}
fn list(p:&Path,out:&mut Vec<String>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir(){list(&e.path(),out)}else{assert!(e.file_type().unwrap().is_file());out.push(e.path().strip_prefix(D).unwrap().display().to_string());}}}
fn main(){
 assert!(!Path::new(D).exists());let review:Value=serde_json::from_slice(&fs::read(format!("{R}/review.json")).unwrap()).unwrap();assert_eq!(review["passed"],true);
 copy(format!("{R}/report.md"),format!("{D}/README.md"));for f in["design.md","native-next.md","base.rs","base-fixed.rs","direct.rs","direct-fixed.rs","driver.rs","driver-fixed.rs","algebra-direct.json","review.rs","review.json","review.log","prepare.rs","prepare.log","repair-test.rs","repair-test.log","repair-link.rs","repair-link.log","pins.json","pins-fixed.json","pins-rest.json","plan.json","plan-fixed.json","plan-rest.json","workflow.log","workflow-fixed.log","workflow-rest.log","publish.rs"]{copy(format!("{R}/{f}"),format!("{D}/artifacts/{f}"));}
 let mut encoded_streams=0;for(root,steps)in[("runs",vec!["compile-direct-tests"]),("runs-fixed",vec!["compile-direct-tests","new-direct-tests","compile-full-domain"]),("runs-rest",vec!["compile-full-domain","full-domain-direct"])]{
  for f in["protocol.json","source-pins.json","completed.json","progress.json","result.json","attempt-0.json"]{let src=format!("{R}/{root}/{f}");if Path::new(&src).exists(){copy(src,format!("{D}/artifacts/receipts/{root}/{f}"));}}
  for step in steps{for f in["command.json","exit.json","tests.json"]{let src=format!("{R}/{root}/{step}/{f}");if Path::new(&src).exists(){copy(src,format!("{D}/artifacts/receipts/{root}/{step}/{f}"));}}
   for stream in["stdout","stderr"]{let src=format!("{R}/{root}/{step}/{stream}.log");let original=fs::read(&src).unwrap();let object=json!({"encoding":"UTF-8 JSON string","original_member":format!("{stream}.log"),"sha256":hash(&src),"text":String::from_utf8(original.clone()).unwrap()});let encoded=serde_json::to_vec_pretty(&object).unwrap();let restored:Value=serde_json::from_slice(&encoded).unwrap();assert_eq!(restored["text"].as_str().unwrap().as_bytes(),original);fs::write(format!("{D}/artifacts/receipts/{root}/{step}/{stream}.log.json"),encoded).unwrap();encoded_streams+=1;}
  }
 }
 let mut files=Vec::new();list(Path::new(D),&mut files);files.sort();let index=files.iter().map(|f|(f.clone(),json!({"sha256":hash(format!("{D}/{f}")),"bytes":fs::metadata(format!("{D}/{f}")).unwrap().len()}))).collect::<BTreeMap<_,_>>();fs::write(format!("{D}/artifact-index.json"),serde_json::to_vec_pretty(&index).unwrap()).unwrap();
 let text=fs::read_to_string(format!("{D}/README.md")).unwrap();let mut links=0;for tail in text.split("](").skip(1){let target=tail.split_once(')').unwrap().0;if target.starts_with("https://"){continue;}assert!(Path::new(D).join(target).is_file());links+=1;}
 let review=json!({"passed":true,"files_before_indices":files.len(),"encoded_streams_roundtrip_exact":encoded_streams,"local_readme_links_checked":links,"archives_created":false,"private_payloads_or_binaries_published":false,"new_proofs":0});fs::write(format!("{R}/publication-review.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();copy(format!("{R}/publication-review.json"),format!("{D}/publication-review.json"));files.clear();list(Path::new(D),&mut files);files.sort();fs::write(format!("{D}/SHA256SUMS"),files.iter().map(|f|format!("{}  {f}\n",hash(format!("{D}/{f}")))).collect::<String>()).unwrap();for(f,v)in index{assert_eq!(hash(format!("{D}/{f}")),v["sha256"].as_str().unwrap());}println!("PublicationPASS {}checksums/{}local links/{}encodedstreams roundtrip exact;no binaries/privatearrays",files.len(),links,encoded_streams);
}
